/* eslint-env jest */
'use strict';

describe('YandexLogger. Streams. Default', () => {
    let jestFakeTimers;
    let lineStream;
    let qloudStream;
    let defaultStream;

    // Mocking the require calls
    jest.mock('../../streams/line', () => jest.fn().mockReturnValue('line'));
    jest.mock('../../streams/qloud', () => jest.fn().mockReturnValue('qloud'));

    const mockedLineStream = require('../../streams/line');
    const mockedQloudStream = require('../../streams/qloud');

    beforeEach(() => {
        lineStream = mockedLineStream;
        qloudStream = mockedQloudStream;

        // Assuming defaultStream requires lineStream and qloudStream dynamically,
        // so we require it here after they are mocked
        defaultStream = require('../../streams/default');

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();

        delete process.env.QLOUD_LOGGER_STDERR_PARSER;

        // Clear all mock calls
        lineStream.mockClear();
        qloudStream.mockClear();
    });

    it('должен создать line stream', () => {
        process.env.QLOUD_LOGGER_STDERR_PARSER = 'line';

        const stream = defaultStream({ line: 'line-config', qloud: 'qloud-config' });

        expect(stream).toBe('line');

        expect(lineStream).toHaveBeenCalledWith('line-config');
        expect(lineStream).toHaveBeenCalledTimes(1);

        expect(qloudStream).not.toHaveBeenCalled();
    });

    it('должен создать qloud stream', () => {
        process.env.QLOUD_LOGGER_STDERR_PARSER = 'json';

        const stream = defaultStream({ line: 'line-config', qloud: 'qloud-config' });

        expect(stream).toBe('qloud');

        expect(qloudStream).toHaveBeenCalledWith('qloud-config');
        expect(qloudStream).toHaveBeenCalledTimes(1);

        expect(lineStream).not.toHaveBeenCalled();
    });
});
